{
  "root_causes": [
    {
      "service": "recommendation",
      "fault_kind": "pod_failure",
      "evidence": [
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name pod, metric, min(value) mn, max(value) mx, count(*) n FROM abnormal_metrics WHERE metric IN ('k8s.container.restarts') AND attr_k8s_pod_name LIKE 'recommendation%' GROUP BY ALL", "claim": "recommendation pod restart counter climbs from 2 to 6 during the incident; it was 0 in normal."},
        {"kind": "metric", "sql": "SELECT 'abn' p, attr_k8s_pod_name pod, metric, round(avg(value),2) av FROM abnormal_metrics WHERE metric='k8s.container.ready' AND attr_k8s_pod_name LIKE 'recommendation%' GROUP BY ALL UNION ALL SELECT 'norm', attr_k8s_pod_name, metric, round(avg(value),2) FROM normal_metrics WHERE metric='k8s.container.ready' AND attr_k8s_pod_name LIKE 'recommendation%' GROUP BY ALL", "claim": "recommendation container readiness averages 0.0 in abnormal versus 1.0 in normal."},
        {"kind": "trace", "sql": "SELECT 'abn' p, count(*) c FROM abnormal_traces WHERE service_name='recommendation' UNION ALL SELECT 'norm', count(*) FROM normal_traces WHERE service_name='recommendation'", "claim": "recommendation emits zero spans in the abnormal window versus 664 in normal."},
        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code code, count(*) c FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /recommendations' GROUP BY ALL", "claim": "All 176 frontend /recommendations requests returned HTTP 500 during the incident."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) c FROM abnormal_logs WHERE service_name='frontend' AND message='Recommendation service failed' GROUP BY ALL", "claim": "Frontend logs 'Recommendation service failed' 876 times at ERROR level."},
        {"kind": "log", "sql": "SELECT count(*) c, any_value(message) msg FROM abnormal_logs WHERE message LIKE '%hotel-reserv-recommendation definition changed%' GROUP BY ALL", "claim": "Kubelet event shows the recommendation container was killed and restarted after a definition change."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code code, count(*) c, round(avg(duration)/1e6,2) ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /recommendations' GROUP BY ALL", "claim": "Frontend's /recommendations path fails with 500s while the recommendation service is down; other frontend paths stay 200."}
      ]
    }
  ]
}
